function pushHistory(changed=true){history=history.slice(0,historyIndex+1);history.push(ctx.getImageData(0,0,W,H));if(history.length>20)history.shift();historyIndex=history.length-1;$('#undoBtn').disabled=historyIndex<=0;$('#redoBtn').disabled=true;if(changed){dirty=true;scheduleSave()}}
