async function acceptFile(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Izaberi JPG, PNG ili WebP sliku.');return}if(file.size>15*1024*1024){toast('Slika je prevelika. Izaberi sliku manju od 15 MB.');return}const url=URL.createObjectURL(file);try{const im=await loadImage(url);uploadImage=im;originalCtx.fillStyle='white';originalCtx.fillRect(0,0,W,H);const scale=Math.min((W-40)/im.naturalWidth,(H-40)/im.naturalHeight);const w=im.naturalWidth*scale,h=im.naturalHeight*scale;originalCtx.drawImage(im,(W-w)/2,(H-h)/2,w,h);$('#uploadEmpty').hidden=true;$('#uploadEditor').hidden=false;compareOriginal=false;$('#compareBtn').textContent='Prikaži original';$('#detailRange').value=48;$('#lineRange').value=1;$('#simplifyCheck').checked=true;processImage();}catch{toast('Ovu sliku nije moguće otvoriti. Probaj drugu.')}finally{URL.revokeObjectURL(url);$('#fileInput').value=''}}
