function processImage(){if(!uploadImage)return;const source=originalCtx.getImageData(0,0,W,H).data,n=W*H,gray=new Float32Array(n);for(let p=0;p<n;p++){const i=p*4;gray[p]=source[i]*.299+source[i+1]*.587+source[i+2]*.114}let blurred=gray;if($('#simplifyCheck').checked){blurred=new Float32Array(n);for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++){const p=y*W+x;blurred[p]=(gray[p-W-1]+2*gray[p-W]+gray[p-W+1]+2*gray[p-1]+4*gray[p]+2*gray[p+1]+gray[p+W-1]+2*gray[p+W]+gray[p+W+1])/16}}const mask=new Uint8Array(n),threshold=125-Number($('#detailRange').value);for(let y=2;y<H-2;y++)for(let x=2;x<W-2;x++){const p=y*W+x,gx=-blurred[p-W-1]+blurred[p-W+1]-2*blurred[p-1]+2*blurred[p+1]-blurred[p+W-1]+blurred[p+W+1],gy=-blurred[p-W-1]-2*blurred[p-W]-blurred[p-W+1]+blurred[p+W-1]+2*blurred[p+W]+blurred[p+W+1];if(Math.sqrt(gx*gx+gy*gy)>threshold)mask[p]=1}let final=mask;const radius=Number($('#lineRange').value)-1;if(radius){final=new Uint8Array(n);for(let y=radius;y<H-radius;y++)for(let x=radius;x<W-radius;x++){const p=y*W+x;if(mask[p])for(let j=-radius;j<=radius;j++)for(let k=-radius;k<=radius;k++)final[p+j*W+k]=1}}const out=pc.createImageData(W,H);for(let p=0;p<n;p++){const i=p*4,v=final[p]?48:255;out.data[i]=out.data[i+1]=out.data[i+2]=v;out.data[i+3]=255}pc.putImageData(out,0,0);convertedURL=$('#convertPreview').toDataURL();compareOriginal=false;$('#compareBtn').textContent='Prikaži original'}
['#detailRange','#lineRange','#simplifyCheck'].forEach(s=>$(s).oninput=()=>{clearTimeout(convertTimer);convertTimer=setTimeout(processImage,80)});$('#compareBtn').onclick=async()=>{compareOriginal=!compareOriginal;$('#compareBtn').textContent=compareOriginal?'Prikaži bojanku':'Prikaži original';if(compareOriginal)pc.drawImage(originalCanvas,0,0);else pc.drawImage(await loadImage(convertedURL),0,0)};
